// === Tab: mySketch ===
function setup() {
  createCanvas(windowWidth, windowHeight);
}

function contrast(value) {
  return 0.5 + 0.5 * sin(value * PI - HALF_PI);
}

function n_contrast(value, n) {
  for (let i = 0; i < n; i++) {
    value = contrast(value);
  }
  return value;
}

function posAt(t, s, n) {
  let y = n_contrast(t * s * 0.001, 1);
  let x = n_contrast(t * (s * 0.001 + 0.0001), 1);

  x *= 0.5 + noise(t * s * 0.001, n) * 1;
  y *= 0.5 + noise(t * (s * 0.001 + 0.0001), n) * 1;

  x = (1 - 2 * x) * 0.3;
  y = (1 - 2 * y) * 0.3;
  return [x, y];
}

function particle(n, speed = 1, offs = 50) {



  let d = 5;

  for (let i = 0; i < 1; i += 1/d) {

    let b = 255 * 1 * (0.5 + 0.5*noise(n));
    stroke(b, b, b, i*255);
    strokeWeight(0.02/(2-i));

    line(...posAt(millis() + i*offs, speed, n), ...posAt(millis() + (i+1)*offs, speed, n));
  }
}

function twoCircles() {
  let r = 0.3+0.3*n_contrast(millis()*2 / 1000, 4);
  let R = 0.3+0.3*n_contrast((millis() + 200 * (1 - 2 * noise(millis()*0.001))) * 2 / 1000, 4);

  fill(r * 200);
  noStroke();

  circle(-0.24*r, 0, r*(0.6 + 0.4 * contrast(noise(millis()*0.001))))
  circle(0.24*R, 0, R*(0.6 + 0.4 * contrast(noise(millis()*0.001))))
}

function particleSystem(x, y, size, n = 40) {
  translate(x, y);
  scale(size);
  for (let i = 0; i < n; i++) {
    particle(i/20, noise(i)*1.2, 5+noise(i)*90);
  }
}

function draw() {

  translate(width/2, height/2);
  scale(width/2);


  background(0.15 * 255);
  particleSystem(sin(millis()/1000*0.2)*0.5, 0, 0.1 + 0.9*n_contrast(abs(sin(millis()/1000*0.1)), 1));

}

